package com.musicclip.visualizer;

import java.util.ArrayList;
import java.util.List;

/** The three royalty-free demo tracks shipped in assets/music (generated by tools/make_music.py). */
public final class BuiltInTracks {
    private BuiltInTracks() {}

    public static final String[][] DEFS = {
            // {id, title, asset path}
            {"neon_skyline", "Neon Skyline", "music/neon_skyline.wav"},
            {"pulse_drive", "Pulse Drive", "music/pulse_drive.wav"},
            {"quiet_orbit", "Quiet Orbit", "music/quiet_orbit.wav"},
    };

    public static List<Track> all() {
        List<Track> out = new ArrayList<>();
        for (String[] d : DEFS) {
            out.add(Track.builtin(d[0], d[1], "MusicClip (synth)", d[2]));
        }
        return out;
    }
}
